input.command:
mkdir -p .cargo tools && cat > tools/zig-cc-x86_64-windows-gnu <<'EOF'
#!/bin/sh
# Linker shim: use `zig cc` as a MinGW-w64 linker for x86_64-pc-windows-gnu.
# Override the zig invocation with ZIG=/path/to/zig if desired.
ZIG="${ZIG:-$(dirname "$0")/../.tools/venv/bin/python -m ziglang}"
# Drop libs zig's bundled mingw doesn't ship / provides itself.
for a in "$@"; do
  shift
  case "$a" in
    -lgcc_eh|-lgcc_s|-l:libpthread.a) ;;
    *) set -- "$@" "$a" ;;
  esac
done
exec $ZIG cc -target x86_64-windows-gnu "$@"
EOF
chmod +x tools/zig-cc-x86_64-windows-gnu
cat > .cargo/config.toml <<'EOF'
[build]
target = "x86_64-pc-windows-gnu"

[target.x86_64-pc-windows-gnu]
# Use the system MinGW-w64 toolchain if installed (`x86_64-w64-mingw32-gcc`);
# otherwise this zig-based shim works without root.
linker = "tools/zig-cc-x86_64-windows-gnu"
EOF
cat > src/main.rs <<'EOF'
use windows_sys::Win32::System::Threading::GetCurrentProcessId;
use windows_sys::Win32::UI::WindowsAndMessaging::{MB_OK, MessageBoxA};

fn main() {
    let pid = unsafe { GetCurrentProcessId() };
    println!("Hello from Windows! PID = {pid}");

    let text = format!("Running as process {pid}\0");
    unsafe {
        MessageBoxA(
            std::ptr::null_mut(),
            text.as_ptr(),
            c"win_app".as_ptr().cast(),
            MB_OK,
        );
    }
}
EOF
printf '/target\n/.tools\n' > .gitignore
cargo build 2>&1 | tail -15

